import sys
import xml.etree.ElementTree as ET
import hashlib
from datetime import datetime

def compute_fingerprint(key, value):
    combined = key + "\x00" + value
    return hashlib.md5(combined.encode('utf-8')).hexdigest()[:16].lower()

def parse_config_file(xml_path):
    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()
        entries = {}
        for entry in root.findall('entry'):
            key = entry.get('key')
            value = entry.get('value')
            if key is not None:
                entries[key] = value
        return entries
    except (IOError, ET.ParseError):
        sys.stderr.write("ERROR cannot read config\n")
        sys.exit(2)

def main():
    if len(sys.argv) != 2:
        sys.stderr.write("ERROR missing XML file path\n")
        sys.exit(2)

    config_entries = parse_config_file(sys.argv[1])

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue

        key = line
        value = config_entries.get(key, "MISSING")
        fingerprint = compute_fingerprint(key, value)

        sys.stdout.write(f"{key}\t{value}\t{fingerprint}\n")

        if value != "MISSING":
            sys.stderr.write(f"{datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ')} INFO key={key} result=found\n")
        else:
            sys.stderr.write(f"{datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ')} WARN key={key} result=missing\n")

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET
from datetime import datetime, timezone
import hashlib

def generate_fingerprint(key_value):
    combined = key_value.encode('utf-8') + b'\x00'
    return hashlib.sha256(combined).hexdigest()[:16].lower()

def process_config_file(xml_path, key):
    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()
        found = False
        for entry in root.findall('entry'):
            if entry.get('key') == key:
                value = entry.get('value')
                fingerprint = generate_fingerprint(f"{key}{value}")
                print(f"{key}\t{value}\t{fingerprint}")
                found = True
                break
        if not found:
            print(f"{key}\tMISSING\t-")
    except (IOError, ET.ParseError):
        print("ERROR cannot read config", file=sys.stderr)
        sys.exit(2)

def log_info(key, result):
    timestamp = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    if result == "found":
        print(f"INFO key={key} result=found", file=sys.stderr)
    else:
        print(f"WARN key={key} result=missing", file=sys.stderr)

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python config_lookup.py <config_file_path> <key>", file=sys.stderr)
        sys.exit(1)

    xml_path = sys.argv[1]
    key = sys.argv[2]
    log_info(key, "missing")
    process_config_file(xml_path, key)

